// ===== Récupération de la réponse =====
const response = pm.response;
const posts = response.json(); // Corps de la réponse converti en objet JavaScript

// ===== 1. Tests sur la réponse HTTP =====
pm.test("Le statut est 200 OK", () => {
    pm.response.to.have.status(200);
});

pm.test("Le temps de réponse est inférieur à 1000 ms", () => {
    pm.expect(response.responseTime).to.be.below(1000);
});

pm.test("Le Content-Type est du JSON", () => {
    pm.response.to.have.header("Content-Type");
    pm.expect(response.headers.get("Content-Type")).to.include("application/json");
});

// ===== 2. Tests sur la structure globale =====
pm.test("La réponse est un tableau non vide", () => {
    pm.expect(posts).to.be.an("array").that.is.not.empty;
});

pm.test("L'API retourne bien 100 posts", () => {
    pm.expect(posts).to.have.lengthOf(100);
});

// ===== 3. Tests sur le contenu de chaque post =====
pm.test("Chaque post contient les bons champs avec les bons types", () => {
    posts.forEach((post) => {
        pm.expect(post).to.have.all.keys("userId", "id", "title", "body");
        pm.expect(post.userId).to.be.a("number");
        pm.expect(post.id).to.be.a("number");
        pm.expect(post.title).to.be.a("string").and.not.empty;
        pm.expect(post.body).to.be.a("string").and.not.empty;
    });
});

pm.test("Les identifiants (id) sont uniques", () => {
    const ids = posts.map((post) => post.id);
    const uniqueIds = new Set(ids);
    pm.expect(uniqueIds.size).to.equal(ids.length);
});

// ===== 4. Test sur un cas précis =====
pm.test("Le premier post a l'id 1 et appartient à l'utilisateur 1", () => {
    pm.expect(posts[0].id).to.equal(1);
    pm.expect(posts[0].userId).to.equal(1);
});

pm.test("Return a valid post", () => {
    pm.response.to.have.status(200);

    const jsonResponse = pm.response.json();

    // Verify properties existence
    pm.expect(jsonResponse).to.include.all.keys('id', 'title', 'body');
    pm.expect(jsonResponse).to.have.property('id', 1);
    pm.expect(jsonResponse).to.have.property('title');
    pm.expect(jsonResponse).to.have.property('body');

    // Type verification
    pm.expect(jsonResponse.title).to.be.a('string');
    pm.expect(jsonResponse.body).to.be.a('string');

    // Values verification
    pm.expect(jsonResponse.title.trim()).to.not.be.empty.and.not.be.null;
    pm.expect(jsonResponse.body.trim()).to.not.be.empty.and.not.be.null;
});
